function charge(rows) {
  const valid = rows.filter(([s, e, r]) => s < e);
  if (valid.length === 0) return 0;
  const points = new Set();
  for (const [s, e] of valid) {
    points.add(s);
    points.add(e);
  }
  const sorted = Array.from(points).sort((a, b) => a - b);
  let total = 0;
  for (let i = 0; i < sorted.length - 1; i++) {
    const a = sorted[i];
    const b = sorted[i + 1];
    let maxRate = 0;
    for (const [s, e, r] of valid) {
      if (s <= a && e >= b) {
        if (r > maxRate) maxRate = r;
      }
    }
    total += (b - a) * maxRate;
  }
  return total;
}

