function activeDays({groups,key}){
  const chain=[];
  const seen=new Set();
  let name=key;
  while(name!==null&&name!==undefined&&Object.prototype.hasOwnProperty.call(groups,name)&&!seen.has(name)){
    seen.add(name);
    chain.push(groups[name]);
    name=groups[name].parent;
  }
  const active=new Set();
  for(let i=chain.length-1;i>=0;i--){
    const entry=chain[i];
    const remove=entry.remove||[];
    const add=entry.add||[];
    for(const d of remove){
      active.delete(d);
    }
    for(const d of add){
      active.add(d);
    }
  }
  return Array.from(active).sort((a,b)=>a-b);
}

