function tranches({budget,rows}){
  const alloc = rows.map(()=>0);
  const order = rows.map((r,i)=>i).sort((a,b)=>rows[a][0]-rows[b][0]||a-b);
  let i = 0;
  while(i < order.length && budget > 0){
    const p = rows[order[i]][0];
    const group = [];
    while(i < order.length && rows[order[i]][0] === p){
      group.push(order[i]);
      i++;
    }
    let active = group.filter(idx=>alloc[idx] < rows[idx][1]);
    while(budget > 0 && active.length > 0){
      const next = [];
      for(const idx of active){
        if(budget <= 0) break;
        if(alloc[idx] < rows[idx][1]){
          alloc[idx]++;
          budget--;
        }
        if(alloc[idx] < rows[idx][1]) next.push(idx);
      }
      active = next;
    }
  }
  return alloc;
}

