function tranches({budget,rows}){
  const alloc = rows.map(()=>0);
  const priorities = [...new Set(rows.map(r=>r[0]))].sort((a,b)=>a-b);
  for(const p of priorities){
    const idxs = [];
    for(let i=0;i<rows.length;i++) if(rows[i][0]===p) idxs.push(i);
    let remaining = idxs.reduce((s,i)=>s+rows[i][1]-alloc[i],0);
    while(budget>0 && remaining>0){
      let progressed = false;
      for(const i of idxs){
        if(budget<=0) break;
        if(alloc[i]<rows[i][1]){
          alloc[i]++;
          budget--;
          remaining--;
          progressed = true;
        }
      }
      if(!progressed) break;
    }
    if(budget<=0) break;
  }
  return alloc;
}

