function leaders({limit, updates}) {
  const scores = new Map();
  for (const [id, score] of updates) {
    if (score === null) {
      scores.delete(id);
    } else {
      scores.set(id, score);
    }
  }
  const entries = Array.from(scores.entries());
  entries.sort((a, b) => {
    if (b[1] !== a[1]) return b[1] - a[1];
    if (a[0] < b[0]) return -1;
    if (a[0] > b[0]) return 1;
    return 0;
  });
  return entries.slice(0, limit).map(([id]) => id);
}

