function coupons(rows) {
  const state = new Map();
  let total = 0;
  let peak = 0;
  for (const row of rows) {
    const action = row[0];
    const id = row[1];
    const value = row[2];
    if (action === 'apply') {
      if (!state.has(id) && value >= 0) {
        state.set(id, value);
        total += value;
        if (total > peak) peak = total;
      }
    } else if (action === 'void') {
      if (state.has(id)) {
        total -= state.get(id);
        state.delete(id);
      }
    }
  }
  return [peak, total];
}

