function coupons(rows) {
  const active = new Map();
  let total = 0;
  let peak = 0;
  for (const row of rows) {
    const action = row[0];
    const id = row[1];
    const value = row[2];
    if (action === 'apply') {
      if (!active.has(id)) {
        active.set(id, value);
        total += value;
        if (total > peak) peak = total;
      }
    } else if (action === 'void') {
      if (active.has(id)) {
        total -= active.get(id);
        active.delete(id);
      }
    }
  }
  return [peak, total];
}

