  let active = false;
  let start = -1;
  let lowRun = 0;
  for (let i = 0; i < samples.length; i++) {
    const v = samples[i];
    if (!active) {
      if (v >= high) {
        active = true;
        start = i;
        lowRun = 0;
      }
    } else {
      if (v <= low) {
        lowRun++;
        if (lowRun === 2) {
          result.push([start, i - 1]);
          active = false;
          start = -1;
          lowRun = 0;
        }
      } else {
        lowRun = 0;
      }
    }
  }
  if (active) {
    result.push([start, samples.length]);
  }
  return result;
}
